import{_ as a,o as i,c as r,ag as o}from"./chunks/framework.D9ghT4bC.js";const m=JSON.parse('{"title":"创建新文明","description":"","frontmatter":{"title":"创建新文明"},"headers":[],"relativePath":"zh/Modders/Making-a-new-Civilization.md","filePath":"zh/Modders/Making-a-new-Civilization.md"}'),t={name:"zh/Modders/Making-a-new-Civilization.md"};function n(l,e,s,d,h,c){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="我的第一个模组-创建新文明" tabindex="-1">&#39;我的第一个模组&#39; - 创建新文明 <a class="header-anchor" href="#我的第一个模组-创建新文明" aria-label="Permalink to &quot;&#39;我的第一个模组&#39; - 创建新文明&quot;">​</a></h1><p>在本教程结束时，你应该有一个可用的、普遍可用的模组，可以向游戏添加一个新的文明</p><h2 id="创建你的仓库" tabindex="-1">创建你的仓库 <a class="header-anchor" href="#创建你的仓库" aria-label="Permalink to &quot;创建你的仓库&quot;">​</a></h2><ul><li>创建一个 <a href="https://github.com/join" target="_blank" rel="noreferrer">Github 账户</a>，如果你还没有的话</li><li>转到 <a href="https://github.com/yairm210/Unciv-mod-example" target="_blank" rel="noreferrer">模组示例</a></li><li>点击绿色的 <code>Use this template</code> 按钮 - <code>Create a new repository</code></li><li>选择你的仓库名称并点击 <code>Create repository from template</code>（保持设置为&#39;public&#39;！）</li><li>你的新仓库现在可用了！</li></ul><h2 id="填写你的文明信息" tabindex="-1">填写你的文明信息 <a class="header-anchor" href="#填写你的文明信息" aria-label="Permalink to &quot;填写你的文明信息&quot;">​</a></h2><p>每个文明都有一些基本信息 - 文明名称、领袖名称、颜色和城市名称。</p><p>此外，每个文明在宣战、介绍等情况下都有一些特色文本。</p><p>所有这些都需要填写在 <code>jsons/Nations.json</code> 文件中 - 有关更多示例，请参阅<a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20&amp;%20Kings/Nations.json" target="_blank" rel="noreferrer">此处</a>的基础游戏文件</p><h2 id="获取你的文明图标" tabindex="-1">获取你的文明图标 <a class="header-anchor" href="#获取你的文明图标" aria-label="Permalink to &quot;获取你的文明图标&quot;">​</a></h2><p>每个文明都有一个图标，例如罗马的花环，用于快速识别。</p><p>所有这些图标都是白色背景透明，大小为 100x100 像素 - 有关详细信息，请参阅<a href="#图标注意事项">图标注意事项</a></p><p>你需要将图标放在 <code>Images/NationIcons</code> 文件夹中 - 你可以导航到那里并点击 <code>Add file - Create a new file</code>（右上角）</p><h2 id="测试它" tabindex="-1">测试它！ <a class="header-anchor" href="#测试它" aria-label="Permalink to &quot;测试它！&quot;">​</a></h2><ul><li>打开 Unciv</li><li>点击&#39;Mods&#39; - &#39;Download mod from URL&#39;</li><li>将你仓库的 URL 复制粘贴到文本框中，并点击&#39;Download&#39;</li><li>退出模组屏幕，并创建一个新游戏，选择你的模组 - 它将在左侧的&#39;Extension mods&#39;下</li></ul><p>恭喜，你的文明现在完全可以玩了！</p><blockquote><p>你目前不会看到来自此模组的任何图像，因为它没有纹理图集 - 有关详细信息，请参阅<a href="/Unciv/zh/Modders/Images-and-Audio.html#图像和纹理图集">此处</a> 如果你在 Desktop 上，你可以重启 Unciv 来生成此图集并查看图像</p></blockquote><p>但是，这个文明的能力与基础模组完全相同。要使其真正独特，我们需要更改一些 Uniques 😉</p><h2 id="添加独特单位" tabindex="-1">添加独特单位 <a class="header-anchor" href="#添加独特单位" aria-label="Permalink to &quot;添加独特单位&quot;">​</a></h2><p>单位在 <code>jsons/Units.json</code> 中定义 - 有关基础游戏文件，请参阅<a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20&amp;%20Kings/Units.json" target="_blank" rel="noreferrer">此处</a>文件，图标在 <a href="https://github.com/yairm210/Unciv/tree/master/android/Images.Construction/UnitIcons" target="_blank" rel="noreferrer">UnitIcons</a> 文件夹中。</p><p>图标必须是 200x200 像素，白色背景透明 - 有关详细信息，请参阅<a href="#图标注意事项">图标注意事项</a> - 并放在 <code>Images/UnitIcons</code> 文件夹中</p><p>请记住这些是独特单位，所以搜索现有的独特单位以查看它们如何替换其常规对应物！</p><h2 id="添加独特建筑" tabindex="-1">添加独特建筑 <a class="header-anchor" href="#添加独特建筑" aria-label="Permalink to &quot;添加独特建筑&quot;">​</a></h2><p>与单位相同 - 信息在 <code>jsons/Buildings.json</code> 中 - 有关基础游戏文件，请参阅 <a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20&amp;%20Kings/Buildings.json" target="_blank" rel="noreferrer">Buildings.json</a>文件，图标在 <a href="https://github.com/yairm210/Unciv/tree/master/android/Images.Construction/BuildingIcons" target="_blank" rel="noreferrer">BuildingIcons</a> 文件夹中，相同的图标规则适用（200x200 像素，图标注意事项）</p><p>图标放在 <code>Images/BuildingIcons</code></p><h2 id="文明独特能力" tabindex="-1">文明独特能力 <a class="header-anchor" href="#文明独特能力" aria-label="Permalink to &quot;文明独特能力&quot;">​</a></h2><p>查看我们的 <a href="/Unciv/zh/Modders/uniques.html">Unique 列表</a>，了解你可以为你的文明添加的所有很酷的特殊效果！</p><h2 id="使其可搜索" tabindex="-1">使其可搜索！ <a class="header-anchor" href="#使其可搜索" aria-label="Permalink to &quot;使其可搜索！&quot;">​</a></h2><p>要将你的模组列在 Unciv 模组屏幕上：</p><ul><li><p>打开你的仓库</p></li><li><p>点击&#39;About&#39;标签右侧的齿轮图标（右侧，顶部）</p></li><li><p>在&#39;Topics&#39;下，添加&#39;unciv-mod&#39;</p></li><li><p>&#39;Save changes&#39;</p></li></ul><p>恭喜，你的模组现在将显示在模组页面上！</p><p>你的仓库拥有的星标越多，它出现的越靠前，所以开始获得粉丝吧 😄</p><h2 id="图标注意事项" tabindex="-1">图标注意事项 <a class="header-anchor" href="#图标注意事项" aria-label="Permalink to &quot;图标注意事项&quot;">​</a></h2><p>所有图标必须在法律上可接受，这意味着它们要么来自开放来源，要么你根据其许可证行事（例如，对于 Creative Commons，你必须指定来源和创建者）。</p><p>直接来自基础游戏的图标属于 Firaxis，所以我不确定我们在法律上被允许使用它们 - 请使用其他来源！</p><p>我不断使用的一个来源是 <a href="https://thenounproject.com" target="_blank" rel="noreferrer">The Noun Project</a> - 那里的所有东西都是 Creative Commons 或开放的，所以它们都可以使用！</p><p>图标的致谢应该在 <code>Credits.md</code> 页面中。</p><h2 id="接下来做什么" tabindex="-1">接下来做什么？ <a class="header-anchor" href="#接下来做什么" aria-label="Permalink to &quot;接下来做什么？&quot;">​</a></h2><p>你有一个可用的模组，现在是时候尽情发挥了！</p><ul><li>将 <a href="/Unciv/zh/Modders/Images-and-Audio.html#图像和纹理图集">atlas 文件</a> 添加到你的仓库中，以便你的用户获得图像</li><li>在本地安装 Git，以便你可以在你的设备上更改文件并将这些更改反映到你的仓库中</li><li>通过添加新的 <a href="/Unciv/zh/Modders/uniques.html">Uniques</a> 来扩展你的文明的能力</li><li>添加新的文明、建筑或单位</li><li>通过探索 <a href="/Unciv/zh/Modders/Mod-file-structure/1-Overview.html">模组文件结构</a>的其余部分来扩展到其他游戏对象</li><li>尝试<a href="https://github.com/yairm210/Unciv-minimal-base-ruleset" target="_blank" rel="noreferrer">从此模板</a>创建基础规则集</li></ul>',39)])])}const u=a(t,[["render",n]]);export{m as __pageData,u as default};
